CREATE DATABASE IF NOT EXISTS gaokao_score CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE gaokao_score;
CREATE TABLE admins(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(64) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE exams(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_date DATE NOT NULL,exam_name VARCHAR(255) NOT NULL,chinese DECIMAL(6,2) DEFAULT 0,math DECIMAL(6,2) DEFAULT 0,english DECIMAL(6,2) DEFAULT 0,physics DECIMAL(6,2) DEFAULT 0,chemistry DECIMAL(6,2) DEFAULT 0,biology DECIMAL(6,2) DEFAULT 0,total DECIMAL(7,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
